import json, os, glob

base = '/root/autodl-tmp/eval_results'
# Check all l01 related files
for pattern in ['*l01*', '*lambda*01*', '*high*']:
    for fp in sorted(glob.glob(os.path.join(base, pattern))):
        if fp.endswith('.json'):
            try:
                with open(fp) as f:
                    data = json.load(f)
                ckpt = data['config'].get('checkpoint', 'N/A')
                print(f"\n{os.path.basename(fp)}:")
                print(f"  ckpt: ...{ckpt[-60:]}")
                for t in data['results']:
                    tn = t['task_name'].split('_and_')[0].replace('pick_up_the_','')
                    print(f"  {tn:25s} CAR={t['CAR']*100:.1f}  TSR={t['TSR']*100:.1f}")
            except Exception as e:
                print(f"{os.path.basename(fp)}: ERROR {e}")
PYEOF
